pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});
    const t = target.result;
    const is_darwin = t.os.tag.isDarwin();

    const omit_frame_pointer = true;
    const pic = true;
    const lib = b.addLibrary(.{ .name = "ffmpeg", .root_module = b.createModule(.{
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .omit_frame_pointer = omit_frame_pointer,
        .pic = pic,
        .strip = true,
    }) });
    lib.root_module.addIncludePath(b.path("."));

    const mod = lib.root_module;

    // libudev-zero
    const udev_upstream = b.dependency("udev_zero", .{});
    const libudev = b.addLibrary(.{ .name = "udev", .linkage = .static, .root_module = b.createModule(.{
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .omit_frame_pointer = omit_frame_pointer,
        .pic = pic,
        .strip = true,
    }) });
    libudev.root_module.addIncludePath(udev_upstream.path("."));
    libudev.root_module.addCSourceFiles(.{
        .root = udev_upstream.path("."),
        .files = libudev_sources,
        .flags = &.{ "-std=c99", "-D_XOPEN_SOURCE=700" },
    });
    mod.addIncludePath(udev_upstream.path("."));
    mod.linkLibrary(libudev);

    // libdrm
    const drm_upstream = b.dependency("libdrm", .{});
    const prepare_header = b.addSystemCommand(&.{"python3"});
    prepare_header.addFileArg(drm_upstream.path("gen_table_fourcc.py"));
    prepare_header.addFileArg(drm_upstream.path("include/drm/drm_fourcc.h"));
    const drm_header = prepare_header.addOutputFileArg("generated_static_table_fourcc.h");
    const libdrm = b.addLibrary(.{ .name = "drm", .linkage = .static, .root_module = b.createModule(.{
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .omit_frame_pointer = omit_frame_pointer,
        .pic = pic,
        .strip = true,
    }) });
    libdrm.root_module.addIncludePath(drm_upstream.path("."));
    libdrm.root_module.addIncludePath(drm_upstream.path("include/drm"));
    libdrm.root_module.addIncludePath(drm_header.dirname());
    libdrm.root_module.addCSourceFiles(.{
        .root = drm_upstream.path("."),
        .files = libdrm_sources,
        .flags = &.{"-DMAJOR_IN_SYSMACROS"},
    });
    mod.linkLibrary(libdrm);
    mod.addIncludePath(drm_upstream.path("."));
    mod.addIncludePath(drm_upstream.path("include/drm"));

    // rkmpp
    const mpp_upstream = b.dependency("rkmpp", .{});
    const rkmpp = b.addLibrary(.{
        .name = "rockchip_mpp",
        .linkage = .dynamic,
        .root_module = b.createModule(.{
            .target = target,
            .optimize = optimize,
            .link_libc = true,
            .omit_frame_pointer = omit_frame_pointer,
            .pic = pic,
            .strip = true,
        }),
        .version = .{ .major = 1, .minor = 0, .patch = 0 },
    });
    rkmpp.root_module.addIncludePath(b.path("compat/rkmpp"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("utils"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("osal"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("osal/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("osal/allocator"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("osal/driver/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("osal/linux"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/common"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/base/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/codec/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/codec/dec/common"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/codec/dec/h264"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/codec/dec/h265"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/codec/rc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/common"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/common/h264"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/common/h265"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/rkdec/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/rkdec/common"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/rkdec/common/h264d"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/hal/rkdec/common/h265d"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/vproc/iep"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/vproc/iep2"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/vproc/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("mpp/vproc/vdpp"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("kmpp/inc"));
    rkmpp.root_module.addIncludePath(mpp_upstream.path("kmpp/base/inc"));
    rkmpp.root_module.addCSourceFiles(.{
        .root = mpp_upstream.path("."),
        .files = rkmpp_sources,
        .flags = &.{
            "-D_GNU_SOURCE",
            "-DHAVE_H264D",
            "-DHAVE_H265D",
        },
    });
    b.installArtifact(rkmpp);
    mod.addIncludePath(mpp_upstream.path("inc"));

    const avconfig_h = b.addConfigHeader(.{
        .style = .blank,
        .include_path = "libavutil/avconfig.h",
    }, .{
        .AV_HAVE_BIGENDIAN = t.cpu.arch.endian() == .big,
        .AV_HAVE_FAST_UNALIGNED = fastUnalignedLoads(t),
    });
    lib.root_module.addConfigHeader(avconfig_h);

    const common_config = .{
        .ARCH_AARCH64 = t.cpu.arch.isAARCH64(),
        .ARCH_ALPHA = false,
        .ARCH_ARM = t.cpu.arch.isArm(),
        .ARCH_AVR32 = false,
        .ARCH_AVR32_AP = false,
        .ARCH_AVR32_UC = false,
        .ARCH_BFIN = false,
        .ARCH_IA64 = false,
        .ARCH_LOONGARCH = switch (t.cpu.arch) {
            .loongarch32, .loongarch64 => true,
            else => false,
        },
        .ARCH_LOONGARCH32 = t.cpu.arch == .loongarch32,
        .ARCH_LOONGARCH64 = t.cpu.arch == .loongarch64,
        .ARCH_M68K = t.cpu.arch == .m68k,
        .ARCH_MIPS = switch (t.cpu.arch) {
            .mips, .mipsel => true,
            else => false,
        },
        .ARCH_MIPS64 = switch (t.cpu.arch) {
            .mips64, .mips64el => true,
            else => false,
        },
        .ARCH_PARISC = false,
        .ARCH_PPC = t.cpu.arch.isPowerPC(),
        .ARCH_PPC64 = t.cpu.arch.isPowerPC64(),
        .ARCH_RISCV = t.cpu.arch.isRISCV(),
        .ARCH_S390 = t.cpu.arch == .s390x,
        .ARCH_SH4 = false,
        .ARCH_SPARC = t.cpu.arch.isSPARC(),
        .ARCH_SPARC64 = t.cpu.arch == .sparc64,
        .ARCH_TILEGX = false,
        .ARCH_TILEPRO = false,
        .ARCH_X86 = t.cpu.arch.isX86(),
        .ARCH_X86_32 = have_x86_feat(t, .@"32bit_mode"),
        .ARCH_X86_64 = have_x86_feat(t, .@"64bit"),

        .HAVE_ARMV5TE = have_arm_feat(t, .has_v5te),
        .HAVE_ARMV6 = have_arm_feat(t, .has_v6),
        .HAVE_ARMV6T2 = have_arm_feat(t, .has_v6t2),
        .HAVE_ARMV8 = have_arm_feat(t, .has_v8) or have_aarch64_feat(t, .v8a),
        .HAVE_DOTPROD = have_arm_feat(t, .dotprod) or have_aarch64_feat(t, .dotprod),
        .HAVE_I8MM = have_arm_feat(t, .i8mm) or have_aarch64_feat(t, .i8mm),
        .HAVE_NEON = have_arm_feat(t, .neon) or have_aarch64_feat(t, .neon),
        .HAVE_VFP = have_arm_feat(t, .vfp2),
        .HAVE_VFPV3 = have_arm_feat(t, .vfp3),
        .HAVE_SETEND = false,
        .HAVE_ALTIVEC = have_ppc_feat(t, .altivec),
        .HAVE_DCBZL = false,
        .HAVE_LDBRX = have_ppc_feat(t, .ldbrx),
        .HAVE_POWER8 = have_ppc_feat(t, .power8_vector),
        .HAVE_PPC4XX = have_ppc_feat(t, .ppc4xx),
        .HAVE_VSX = have_ppc_feat(t, .vsx),
        .HAVE_RV = false,
        .HAVE_RVV = false,
        .HAVE_AESNI = have_x86_feat(t, .aes),
        .HAVE_AMD3DNOW = have_x86_feat(t, .@"3dnow"),
        .HAVE_AMD3DNOWEXT = have_x86_feat(t, .@"3dnow"),
        .HAVE_AVX = have_x86_feat(t, .avx),
        .HAVE_AVX2 = have_x86_feat(t, .avx2),
        .HAVE_AVX512 = have_x86_feat(t, .avx512f),
        .HAVE_AVX512ICL = have_x86_feat(t, .avx512f),
        .HAVE_FMA3 = have_x86_feat(t, .fma),
        .HAVE_FMA4 = have_x86_feat(t, .fma4),
        .HAVE_MMX = have_x86_feat(t, .mmx),
        .HAVE_MMXEXT = have_x86_feat(t, .mmx),
        .HAVE_SSE = have_x86_feat(t, .sse),
        .HAVE_SSE2 = have_x86_feat(t, .sse2),
        .HAVE_SSE3 = have_x86_feat(t, .sse3),
        .HAVE_SSE4 = have_x86_feat(t, .sse4_1),
        .HAVE_SSE42 = have_x86_feat(t, .sse4_2),
        .HAVE_SSSE3 = have_x86_feat(t, .ssse3),
        .HAVE_XOP = have_x86_feat(t, .xop),
        .HAVE_I686 = have_x86_feat(t, .cmov) and
            have_x86_feat(t, .cx8) and
            have_x86_feat(t, .vzeroupper) and
            have_x86_feat(t, .x87),
        .HAVE_MIPSFPU = missing_mips_feat(t, .soft_float),
        .HAVE_MIPS32R2 = have_mips_feat(t, .mips32r2),
        .HAVE_MIPS32R5 = have_mips_feat(t, .mips32r5),
        .HAVE_MIPS64R2 = have_mips_feat(t, .mips64r2),
        .HAVE_MIPS32R6 = have_mips_feat(t, .mips32r6),
        .HAVE_MIPS64R6 = have_mips_feat(t, .mips64r6),
        .HAVE_MIPSDSP = have_mips_feat(t, .dsp),
        .HAVE_MIPSDSPR2 = have_mips_feat(t, .dspr2),
        .HAVE_MSA = have_mips_feat(t, .msa),
        .HAVE_LOONGSON2 = false,
        .HAVE_LOONGSON3 = false,
        .HAVE_MMI = false,
        .HAVE_LSX = false,
        .HAVE_LASX = false,

        .HAVE_ARMV5TE_EXTERNAL = have_arm_feat(t, .has_v5te),
        .HAVE_ARMV6_EXTERNAL = have_arm_feat(t, .has_v6),
        .HAVE_ARMV6T2_EXTERNAL = have_arm_feat(t, .has_v6t2),
        .HAVE_ARMV8_EXTERNAL = have_arm_feat(t, .has_v8) or have_aarch64_feat(t, .v8a),
        .HAVE_DOTPROD_EXTERNAL = have_arm_feat(t, .dotprod) or have_aarch64_feat(t, .dotprod),
        .HAVE_I8MM_EXTERNAL = have_arm_feat(t, .i8mm) or have_aarch64_feat(t, .i8mm),
        .HAVE_NEON_EXTERNAL = have_arm_feat(t, .neon) or have_aarch64_feat(t, .neon),
        .HAVE_VFP_EXTERNAL = have_arm_feat(t, .vfp2),
        .HAVE_VFPV3_EXTERNAL = have_arm_feat(t, .vfp3),
        .HAVE_SETEND_EXTERNAL = false,
        .HAVE_ALTIVEC_EXTERNAL = have_ppc_feat(t, .altivec),
        .HAVE_DCBZL_EXTERNAL = false,
        .HAVE_LDBRX_EXTERNAL = have_ppc_feat(t, .ldbrx),
        .HAVE_POWER8_EXTERNAL = have_ppc_feat(t, .power8_vector),
        .HAVE_PPC4XX_EXTERNAL = have_ppc_feat(t, .ppc4xx),
        .HAVE_VSX_EXTERNAL = have_ppc_feat(t, .vsx),
        .HAVE_RV_EXTERNAL = false,
        .HAVE_RVV_EXTERNAL = false,
        .HAVE_AESNI_EXTERNAL = have_x86_feat(t, .aes),
        .HAVE_AMD3DNOW_EXTERNAL = have_x86_feat(t, .@"3dnow"),
        .HAVE_AMD3DNOWEXT_EXTERNAL = have_x86_feat(t, .@"3dnowa"),
        .HAVE_AVX_EXTERNAL = have_x86_feat(t, .avx),
        .HAVE_AVX2_EXTERNAL = have_x86_feat(t, .avx2),
        .HAVE_AVX512_EXTERNAL = have_x86_feat(t, .avx512f),
        .HAVE_AVX512ICL_EXTERNAL = have_x86_feat(t, .avx512f),
        .HAVE_FMA3_EXTERNAL = have_x86_feat(t, .fma),
        .HAVE_FMA4_EXTERNAL = have_x86_feat(t, .fma4),
        .HAVE_MMX_EXTERNAL = have_x86_feat(t, .mmx),
        .HAVE_MMXEXT_EXTERNAL = have_x86_feat(t, .mmx),
