        .EXTERN_PREFIX = switch (t.os.tag) {
            .macos => "_",
            else => "",
        },
    });
    switch (t.os.tag) {
        .macos => config_h.addIdent("EXTERN_ASM", "_"),
        else => config_h.addValues(.{ .EXTERN_ASM = {} }),
    }
