        .CONFIG_PIPE_PROTOCOL = false,
        .CONFIG_PROMPEG_PROTOCOL = false,
        .CONFIG_RTMP_PROTOCOL = false,
        .CONFIG_RTMPE_PROTOCOL = false,
        .CONFIG_RTMPS_PROTOCOL = false,
        .CONFIG_RTMPT_PROTOCOL = false,
        .CONFIG_RTMPTE_PROTOCOL = false,
        .CONFIG_RTMPTS_PROTOCOL = false,
        .CONFIG_RTP_PROTOCOL = true,
        .CONFIG_SCTP_PROTOCOL = false,
        .CONFIG_SRTP_PROTOCOL = false,
        .CONFIG_SUBFILE_PROTOCOL = false,
        .CONFIG_TEE_PROTOCOL = false,
        .CONFIG_TCP_PROTOCOL = true,
        .CONFIG_TLS_PROTOCOL = false,
        .CONFIG_UDP_PROTOCOL = true,
        .CONFIG_UDPLITE_PROTOCOL = false,
        .CONFIG_UNIX_PROTOCOL = false,
        .CONFIG_LIBAMQP_PROTOCOL = false,
        .CONFIG_LIBRIST_PROTOCOL = false,
        .CONFIG_LIBRTMP_PROTOCOL = false,
        .CONFIG_LIBRTMPE_PROTOCOL = false,
        .CONFIG_LIBRTMPS_PROTOCOL = false,
        .CONFIG_LIBRTMPT_PROTOCOL = false,
        .CONFIG_LIBRTMPTE_PROTOCOL = false,
        .CONFIG_LIBSRT_PROTOCOL = false,
        .CONFIG_LIBSSH_PROTOCOL = false,
        .CONFIG_LIBSMBCLIENT_PROTOCOL = false,
        .CONFIG_LIBZMQ_PROTOCOL = false,
        .CONFIG_IPFS_GATEWAY_PROTOCOL = false,
        .CONFIG_IPNS_GATEWAY_PROTOCOL = false,
    });
    lib.root_module.addConfigHeader(config_components_h);

    const sources = categorizeSources(b.allocator, t);

    lib.root_module.addCSourceFiles(.{
        .files = sources.avcodec,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_avcodec"},
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources.avutil,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_avutil"},
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources.avformat,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_avformat"},
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources.avfilter,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_avfilter"},
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources.swresample,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_swresample"},
    });
    lib.root_module.addCSourceFiles(.{
        .files = sources.swscale,
        .flags = ffmpeg_cflags ++ [_][]const u8{"-DBUILDING_swscale"},
    });
    switch (t.cpu.arch) {
        .x86_64, .x86 => {
            // For x86 there is one additional complication which is compiling .asm
            // files into object files with NASM. Prefer a system-installed nasm
            // when available; otherwise fall back to building it from source.
            const system_nasm = b.findProgram(&.{"nasm"}, &.{}) catch null;
            const nasm_exe: ?*std.Build.Step.Compile = if (system_nasm == null) blk: {
                const nasm_dep = b.dependency("nasm", .{
                    .optimize = .ReleaseFast,
                });
                break :blk nasm_dep.artifact("nasm");
            } else null;

            for (all_sources) |input_file| {
                if (!std.mem.endsWith(u8, input_file, ".asm")) continue;

                const output_basename = basenameNewExtension(b, input_file, ".o");
                const nasm_run = if (nasm_exe) |exe|
                    b.addRunArtifact(exe)
                else
                    b.addSystemCommand(&.{system_nasm.?});

                nasm_run.addArgs(&.{ "-f", "elf64", "-g", "-F", "dwarf" });

                // nasm requires a trailing slash on include directories
                nasm_run.addDecoratedDirectoryArg("-I", b.path("."), "/");
                nasm_run.addDecoratedDirectoryArg("-I", b.path(std.fs.path.dirname(input_file).?), "/");

                nasm_run.addArgs(&.{"--include"});
                nasm_run.addFileArg(config_asm.getOutputFile());

                nasm_run.addArgs(&.{"-o"});
                lib.root_module.addObjectFile(nasm_run.addOutputFileArg(output_basename));

                nasm_run.addFileArg(b.path(input_file));
            }
        },
        else => {},
    }

    b.installArtifact(lib);
    lib.installConfigHeader(avconfig_h);
    for (headers) |h| lib.installHeader(b.path(h), h);

    const bindings = b.addModule("av", .{
        .root_source_file = b.path("av.zig"),
        .target = target,
        .optimize = optimize,
    });
    bindings.linkLibrary(lib);

    const show_metadata_c = b.addExecutable(.{
        .name = "show_metadata_c",
        .root_module = b.createModule(.{
            .target = target,
            .optimize = optimize,
        }),
    });
    show_metadata_c.root_module.addCSourceFiles(.{
        .files = &.{"doc/examples/show_metadata.c"},
    });
    show_metadata_c.root_module.linkLibrary(lib);
    b.installArtifact(show_metadata_c);

    const show_metadata_zig = b.addExecutable(.{
        .name = "show_metadata_zig",
        .root_module = b.createModule(.{
            .root_source_file = b.path("doc/examples/show_metadata.zig"),
            .target = target,
            .optimize = optimize,
        }),
    });
    show_metadata_zig.root_module.addImport("av", bindings);
    b.installArtifact(show_metadata_zig);
}

fn osName(os_tag: std.Target.Os.Tag) enum { linux, darwin } {
    return switch (os_tag) {
        .driverkit,
        .ios,
        .maccatalyst,
        .macos,
        .tvos,
        .visionos,
        .watchos,
        => .darwin,
        else => .linux,
    };
}

fn asArchLevel(b: *std.Build, t: std.Target) []const u8 {
    const prefix = if (have_aarch64_feat(t, .v9_6a))
        "armv9.6-a"
    else if (have_aarch64_feat(t, .v9_5a))
        "armv9.5-a"
    else if (have_aarch64_feat(t, .v9_4a))
        "armv9.4-a"
    else if (have_aarch64_feat(t, .v9_3a))
        "armv9.3-a"
    else if (have_aarch64_feat(t, .v9_2a))
        "armv9.2-a"
    else if (have_aarch64_feat(t, .v9_1a))
        "armv9.1-a"
    else if (have_aarch64_feat(t, .v8_9a))
        "armv8.9-a"
    else if (have_aarch64_feat(t, .v8_8a))
        "armv8.8-a"
    else if (have_aarch64_feat(t, .v8_7a))
        "armv8.6-a"
    else if (have_aarch64_feat(t, .v8_6a))
        "armv8.6-a"
    else if (have_aarch64_feat(t, .v8_5a))
        "armv8.5-a"
    else if (have_aarch64_feat(t, .v8_4a))
        "armv8.4-a"
    else if (have_aarch64_feat(t, .v8_3a))
        "armv8.3-a"
    else if (have_aarch64_feat(t, .v8_2a))
        "armv8.2-a"
    else if (have_aarch64_feat(t, .v8_1a))
        "armv8.1-a"
    else
        "armv8-a";

    const crc = if (have_aarch64_feat(t, .crc)) "+crc" else "";

    return b.fmt("{s}{s}", .{ prefix, crc });
}

const CategorizedSources = struct {
    avcodec: []const []const u8,
    avdevice: []const []const u8,
    avfilter: []const []const u8,
    avformat: []const []const u8,
    avutil: []const []const u8,
    swresample: []const []const u8,
    swscale: []const []const u8,
};

/// For x86, files ending in .asm are omitted.
fn categorizeSources(ally: std.mem.Allocator, target: std.Target) CategorizedSources {
    var libs: [@typeInfo(CategorizedSources).@"struct".fields.len]struct {
        prefix: []const u8,
        list: std.ArrayListUnmanaged([]const u8) = .empty,
    } = undefined;

    inline for (@typeInfo(CategorizedSources).@"struct".fields, 0..) |field, i| {
        libs[i] = .{ .prefix = "lib" ++ field.name ++ "/" };
    }
    for (all_sources) |prefixed_path| {
        const path = if (std.mem.startsWith(u8, prefixed_path, "/L/")) p: {
            if (target.os.tag != .linux) continue;
            break :p prefixed_path["/L/".len..];
        } else if (std.mem.startsWith(u8, prefixed_path, "/W/")) p: {
            if (target.os.tag != .windows) continue;
            break :p prefixed_path["/W/".len..];
        } else prefixed_path;

        const lib = for (&libs) |*lib| {
            if (std.mem.startsWith(u8, path, lib.prefix))
                break lib;
        } else {
            std.debug.panic("source file '{s}' is not prefixed with any ffmpeg library name", .{
                path,
            });
        };

        const sub_path = path[lib.prefix.len..];

        // Skip files from wrong targets.
        if (std.mem.startsWith(u8, sub_path, "aarch64/")) {
            if (!target.cpu.arch.isAARCH64()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "arm/")) {
            if (!target.cpu.arch.isArm()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "alpha/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "avr32/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "bfin/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "cuda/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "dnn/") or
            std.mem.startsWith(u8, sub_path, "bsf/") or
            std.mem.startsWith(u8, sub_path, "vvc/") or
            std.mem.startsWith(u8, sub_path, "aac/") or
            std.mem.startsWith(u8, sub_path, "hevc/") or
            std.mem.startsWith(u8, sub_path, "opus/"))
        {
            // This is a component subdirectory, not a target one.
        } else if (std.mem.startsWith(u8, sub_path, "loongarch/")) {
            switch (target.cpu.arch) {
                .loongarch32, .loongarch64 => {},
                else => continue,
            }
        } else if (std.mem.startsWith(u8, sub_path, "metal/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "mips/")) {
            if (!target.cpu.arch.isMIPS()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "neon/")) {
            switch (target.cpu.arch) {
                .arm, .armeb => {
                    if (!std.Target.arm.featureSetHas(target.cpu.features, .neon))
                        continue;
                },
                .aarch64, .aarch64_be => {
                    if (!std.Target.aarch64.featureSetHas(target.cpu.features, .neon))
                        continue;
                },
                else => continue,
            }
        } else if (std.mem.startsWith(u8, sub_path, "opencl/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "ppc/")) {
            if (!target.cpu.arch.isPowerPC()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "riscv/")) {
            if (!target.cpu.arch.isRISCV()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "sh4/")) {
            continue;
        } else if (std.mem.startsWith(u8, sub_path, "sparc/")) {
            if (!target.cpu.arch.isSPARC()) continue;
        } else if (std.mem.startsWith(u8, sub_path, "x86/")) {
            if (!target.cpu.arch.isX86()) continue;
            // These are handled separately because they are passed through nasm.
            if (std.mem.endsWith(u8, sub_path, ".asm")) continue;
        } else if (std.mem.indexOfScalar(u8, sub_path, '/') != null) {
            std.debug.panic("unrecognized subdirectory in path '{s}'", .{path});
        }

        lib.list.append(ally, path) catch @panic("OOM");
    }

    var result: CategorizedSources = undefined;
    inline for (@typeInfo(CategorizedSources).@"struct".fields, 0..) |field, i| {
        @field(result, field.name) = libs[i].list.items;
    }
    return result;
}

